-- =====================================================================
insert into biblioteca (conta_id, nome, setor_nome, tipo, urgencia, dias, como_fazer, origem)
select c.id, m.nome, m.setor, m.tipo, m.urg, m.dias, m.cf, 'Biblioteca Gesta''Up'
from contas c
cross join (values
  ('Confinamento - Tratar dos Animais', 'Gado', '1 - Rotina', 1, '{true,true,true,true,true,true,true}'::boolean[], '{"m2": "1. Conferir a leitura de cocho e a quantidade de cada baia\n2. Carregar o vagão seguindo a ordem e o peso de cada ingrediente da receita\n3. Misturar pelo tempo certo\n4. Distribuir de forma igual em todo o cocho, sempre nos mesmos horários\n5. Anotar o fornecido de cada baia e avisar sobra ou falta", "m3": "Vagão misturador e trator ou pá carregadeira", "m4": "Receita da dieta, planilha de trato", "m5": "Todas as baias tratadas no horário e na quantidade certa", "meta_qtd": 1, "meta_unid": "Trato", "tempo_h": 3, "checklist": ["Leitura de cocho conferida", "Ingredientes pesados conforme a receita", "Tempo de mistura cumprido", "Fornecido anotado por baia"]}'::jsonb),
  ('Confinamento - Molhar Curral (pipa)', 'Operacional', '1 - Rotina', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Encher o pipa com água\n2. Molhar os corredores e as baias com mais poeira\n3. Não encharcar a área do cocho\n4. Repetir nas horas mais secas, se precisar\n5. Anotar quantas cargas foram usadas", "m3": "Trator e pipa", "m4": "Água", "m5": "Curral sem poeira forte", "meta_qtd": 1, "meta_unid": "Rodada", "tempo_h": 2, "checklist": []}'::jsonb),
  ('Gado - Suplementação Fornecimento', 'Máquinas', '1 - Rotina', 1, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Conferir o suplemento e a quantidade de cada lote na lista do dia\n2. Pesar ou medir a quantidade de cada lote\n3. Entregar no cocho sempre no mesmo horário\n4. Conferir se o cocho estava limpo e seco\n5. Anotar o entregue em cada lote", "m3": "Trator com carreta ou vagão", "m4": "Suplemento, balança", "m5": "Todos os lotes suplementados na quantidade certa", "meta_qtd": 1, "meta_unid": "Rodada", "tempo_h": 3, "checklist": []}'::jsonb),
  ('Produzir Ração_ Suplemento', 'Operacional', '1 - Rotina', 1, '{true,true,true,true,true,true,true}'::boolean[], '{"m2": "1. Conferir a receita e o estoque de cada ingrediente\n2. Pesar cada ingrediente na balança\n3. Misturar pelo tempo indicado\n4. Ensacar ou guardar em local seco e identificado\n5. Anotar a quantidade produzida, a receita e a data", "m3": "Misturador, balança", "m4": "Ingredientes da receita, sacaria", "m5": "Lote de ração produzido na receita certa", "meta_qtd": 1, "meta_unid": "Lote", "tempo_h": 3, "checklist": ["Receita conferida", "Ingredientes pesados", "Tempo de mistura cumprido", "Produção anotada"]}'::jsonb),
  ('Gado - Auditoria do Rebanho', 'Gado', '2 - Estratégica', 1, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Pegar a lista do rebanho no sistema ou planilha\n2. Contar cada lote no curral ou no pasto\n3. Conferir categoria (sexo e idade) e brincos\n4. Anotar diferenças: mortes, nascimentos, transferências\n5. Acertar o estoque e explicar as diferenças", "m3": "Curral, cavalo ou moto", "m4": "Lista do rebanho, caneta", "m5": "Rebanho contado e estoque batendo com o sistema", "meta_qtd": 1, "meta_unid": "Auditoria", "tempo_h": 6, "checklist": []}'::jsonb),
  ('Gado - Evolução do Rebanho/Indea', 'Gerencial', '2 - Estratégica', 1, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Juntar os nascimentos, mortes, compras, vendas e mudanças de categoria do período\n2. Lançar a evolução do rebanho\n3. Conferir com o saldo do órgão de defesa\n4. Atualizar a declaração de rebanho no prazo\n5. Guardar o comprovante", "m3": "Computador com internet", "m4": "Relatórios do rebanho, senha do órgão de defesa", "m5": "Saldo do órgão de defesa igual ao da fazenda", "meta_qtd": 1, "meta_unid": "Atualização", "tempo_h": 2, "checklist": []}'::jsonb),
  ('Gado - Compra de Animais', 'Gerencial', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Definir categoria, quantidade, peso e preço máximo\n2. Conferir a origem: sanidade, GTA e vacinas\n3. Pesar ou conferir o peso na chegada\n4. Fazer a quarentena e o manejo de entrada (vermífugo, vacinas, brinco)\n5. Lançar a compra no rebanho e no financeiro", "m3": "Balança, curral", "m4": "GTA, nota fiscal, planilha", "m5": "Animais comprados dentro do combinado e lançados", "meta_qtd": 1, "meta_unid": "Compra", "tempo_h": 4, "checklist": []}'::jsonb),
  ('Auditoria - conferência de estoque medicamentos', 'Operacional', '4 - Estruturação', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Listar os medicamentos e vacinas do estoque\n2. Contar cada item e conferir a validade\n3. Conferir a temperatura da geladeira das vacinas\n4. Separar os vencidos para descarte certo\n5. Atualizar o controle e avisar o que precisa comprar", "m3": "Geladeira, termômetro", "m4": "Planilha de estoque", "m5": "Estoque contado e sem produto vencido no uso", "meta_qtd": 1, "meta_unid": "Conferência", "tempo_h": 2, "checklist": ["Itens contados", "Validades conferidas", "Temperatura da geladeira anotada", "Vencidos separados", "Controle atualizado"]}'::jsonb),
  ('Fábrica - Limpeza', 'Operacional', '1 - Rotina', 2, '{false,false,false,true,false,false,false}'::boolean[], '{"m2": "1. Desligar as máquinas antes de limpar\n2. Varrer e retirar restos de ração e poeira\n3. Limpar o misturador e as roscas\n4. Conferir sinais de rato, inseto ou umidade\n5. Deixar os ingredientes fechados e identificados", "m3": "Vassoura, pá, soprador", "m4": "EPI (máscara), sacos", "m5": "Fábrica limpa e sem ração velha acumulada", "meta_qtd": 1, "meta_unid": "Limpeza", "tempo_h": 3, "checklist": []}'::jsonb),
  ('Fabrica - Manutenção', 'Operacional', '1 - Rotina', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Desligar e travar a energia antes de mexer\n2. Conferir correias, rolamentos e roscas\n3. Engraxar os pontos de lubrificação\n4. Conferir a balança e a parte elétrica\n5. Anotar peças trocadas e o que precisa comprar", "m3": "Chaves, engraxadeira", "m4": "Graxa, correias, peças", "m5": "Fábrica funcionando sem parada por quebra", "meta_qtd": 1, "meta_unid": "Manutenção", "tempo_h": 3, "checklist": ["Energia desligada e travada", "Correias e rolamentos", "Graxa nos pontos", "Balança conferida"]}'::jsonb),
  ('Tropa - Trato Ração', 'Gado', '1 - Rotina', 2, '{true,true,true,true,true,true,false}'::boolean[], '{"m2": "1. Conferir a quantidade de ração de cada animal\n2. Tratar sempre nos mesmos horários\n3. Conferir a água do cocho\n4. Observar se algum animal não comeu\n5. Anotar e avisar o que estiver fora do normal", "m3": "Balde, medida", "m4": "Ração", "m5": "Tropa tratada no horário e na quantidade certa", "meta_qtd": 1, "meta_unid": "Trato", "tempo_h": 0.5, "checklist": []}'::jsonb),
  ('Tropa - Casqueamento', 'Gado', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Amarrar e conter o animal com segurança\n2. Limpar o casco\n3. Aparar e nivelar o casco\n4. Conferir ferradura, se tiver\n5. Anotar o animal e a data", "m3": "Torquês, grosa, rinete", "m4": "Ferraduras e cravos, se precisar", "m5": "Animais com casco aparado e sem mancar", "meta_qtd": 5, "meta_unid": "Animais", "tempo_h": 3, "checklist": []}'::jsonb),
  ('Tropa_Vermifugação e Vacinação', 'Gado', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Conferir os produtos, as doses por peso e a validade\n2. Conter o animal com segurança\n3. Aplicar o vermífugo e as vacinas conforme a bula\n4. Anotar animal, produto e data\n5. Marcar a próxima data", "m3": "Seringas, pistola", "m4": "Vermífugo, vacinas, caixa térmica", "m5": "Tropa tratada e com as datas anotadas", "meta_qtd": 1, "meta_unid": "Tropa", "tempo_h": 2, "checklist": ["Produtos e doses conferidos", "Vacina refrigerada", "Animais anotados", "Próxima data marcada"]}'::jsonb),
  ('Tropa - Combate de Carrapatos', 'Gado', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Conferir o produto e a dose na bula\n2. Aplicar no corpo todo, inclusive orelhas e entre as pernas\n3. Anotar animal, produto e data\n4. Guardar o equipamento e devolver a embalagem", "m3": "Pulverizador costal", "m4": "Carrapaticida, EPI", "m5": "Tropa tratada com o produto e a dose certos", "meta_qtd": 1, "meta_unid": "Tropa", "tempo_h": 1, "checklist": []}'::jsonb),
  ('Bebedouros - Instalação /Manutenção', 'Operacional', '1 - Rotina', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Conferir o nível do terreno e a base do bebedouro\n2. Instalar ou trocar boia, registro e cano\n3. Vedar emendas e conferir vazamentos\n4. Proteger o bebedouro contra o pisoteio (base firme ou cascalho)\n5. Encher e testar a boia", "m3": "Chaves, serra, enxada", "m4": "Boia, registro, canos, conexões, veda-rosca", "m5": "Bebedouro funcionando, sem vazamento e com boia regulada", "meta_qtd": 2, "meta_unid": "Bebedouros", "tempo_h": 4, "checklist": []}'::jsonb),
  ('Cerca - Construção', 'Gado', '4 - Estruturação', 1, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Marcar o alinhamento com estacas e linha\n2. Abrir os buracos dos esticadores e palanques no espaço combinado\n3. Firmar esticadores e palanques bem socados\n4. Passar e esticar os fios na altura certa\n5. Grampear e conferir a tensão de todos os fios", "m3": "Cavadeira, esticador, marreta, alicate", "m4": "Arame, palanques, esticadores, grampos", "m5": "Cerca nova firme e alinhada", "meta_qtd": 500, "meta_unid": "Metros", "tempo_h": 8, "checklist": []}'::jsonb),
  ('Cerca Elétrica - Construção', 'Gado', '4 - Estruturação', 3, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Marcar o alinhamento e limpar a faixa\n2. Fincar as estacas e os cantos firmes\n3. Instalar isoladores e passar o fio na altura certa\n4. Fazer o aterramento conforme o aparelho\n5. Ligar e medir a voltagem no ponto mais longe", "m3": "Cavadeira, marreta, voltímetro", "m4": "Fio, isoladores, estacas, hastes de aterramento", "m5": "Cerca elétrica com choque em toda a linha", "meta_qtd": 1, "meta_unid": "Km", "tempo_h": 8, "checklist": []}'::jsonb),
  ('Cerca Elétrica - Aceiro / Manutenção', 'Gado', '4 - Estruturação', 3, '{false,false,true,false,false,false,false}'::boolean[], '{"m2": "1. Roçar ou capinar a faixa embaixo do fio\n2. Retirar galhos e mato encostando no fio\n3. Trocar isoladores quebrados\n4. Esticar o fio e refazer emendas ruins\n5. Medir a voltagem depois do serviço", "m3": "Roçadeira costal, alicate, voltímetro", "m4": "Isoladores, fio, emendas", "m5": "Linha limpa e com choque", "meta_qtd": 1, "meta_unid": "Km", "tempo_h": 4, "checklist": []}'::jsonb),
  ('Cerca Elétrica - Placa Solar', 'Máquinas', '4 - Estruturação', 3, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Limpar a placa com pano e água, sem produto abrasivo\n2. Conferir os cabos e as conexões\n3. Conferir a carga da bateria\n4. Conferir se a placa está virada para o sol, sem sombra\n5. Medir a voltagem da cerca depois", "m3": "Pano, balde, multímetro", "m4": "Água limpa", "m5": "Placa limpa e bateria carregando", "meta_qtd": 1, "meta_unid": "Placa", "tempo_h": 1, "checklist": []}'::jsonb),
  ('Cerca - Aceiro (gradagem) /(herbicida)', 'Máquinas', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Marcar a faixa de aceiro ao longo da cerca\n2. Gradear ou aplicar o herbicida na largura combinada\n3. Não encostar a grade nos palanques\n4. Conferir se a faixa ficou contínua, sem falhas\n5. Anotar os metros feitos", "m3": "Trator e grade, ou pulverizador", "m4": "Herbicida (se for o caso), EPI", "m5": "Aceiro contínuo na largura certa", "meta_qtd": 2, "meta_unid": "Km", "tempo_h": 6, "checklist": []}'::jsonb),
  ('Cocho - Construção e Montagem', 'Operacional', '4 - Estruturação', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Escolher local alto, firme e de fácil acesso\n2. Montar a base e nivelar\n3. Montar o cocho e a cobertura, se tiver\n4. Fazer os furos de escoamento\n5. Calcular o espaço de cocho por animal", "m3": "Furadeira, serra, nível", "m4": "Material do cocho, parafusos", "m5": "Cocho montado, nivelado e com escoamento", "meta_qtd": 2, "meta_unid": "Cochos", "tempo_h": 6, "checklist": []}'::jsonb),
