  ('Curral - Manutenção Tronco de Contenção', 'Operacional', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Conferir a pescoceira, as portas e as travas\n2. Engraxar as partes móveis\n3. Apertar parafusos e trocar peças gastas\n4. Conferir o piso antiderrapante\n5. Testar com um animal antes do manejo", "m3": "Chaves, engraxadeira", "m4": "Graxa, parafusos, peças", "m5": "Tronco seguro e funcionando", "meta_qtd": 1, "meta_unid": "Tronco", "tempo_h": 2, "checklist": []}'::jsonb),
  ('Porteira - Construção', 'Gado', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Marcar o local e a largura da porteira\n2. Fincar e firmar os mourões no prumo\n3. Instalar as dobradiças e a porteira no nível\n4. Instalar o trinco ou a corrente\n5. Testar abrir e fechar", "m3": "Cavadeira, nível, furadeira", "m4": "Mourões, porteira, dobradiças, trinco", "m5": "Porteira firme, no nível e fechando bem", "meta_qtd": 2, "meta_unid": "Porteiras", "tempo_h": 6, "checklist": []}'::jsonb),
