  ('Pasto - Herbicida - Revisão Pulverizador', 'Máquinas', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Lavar o tanque e as mangueiras\n2. Conferir e limpar os bicos e os filtros\n3. Trocar bicos gastos (vazão diferente)\n4. Conferir mangueiras, vedações e o manômetro\n5. Calibrar a vazão com água antes de usar", "m3": "Chaves, proveta, cronômetro", "m4": "Bicos, filtros, vedações", "m5": "Pulverizador calibrado e sem vazamento", "meta_qtd": 1, "meta_unid": "Pulverizador", "tempo_h": 2, "checklist": ["Tanque lavado", "Bicos e filtros limpos", "Bicos gastos trocados", "Sem vazamento", "Vazão calibrada"]}'::jsonb),
  ('Pasto - Inseticida - Aplicação Cigarrinhas', 'Máquinas', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Avaliar a infestação nos pastos (espuma na base do capim)\n2. Conferir o produto, a dose e o receituário\n3. Aplicar nas horas mais frescas, sem vento\n4. Respeitar a carência antes de voltar o gado\n5. Anotar a área e a data", "m3": "Pulverizador", "m4": "Inseticida, EPI", "m5": "Área tratada e carência respeitada", "meta_qtd": 10, "meta_unid": "Hectares", "tempo_h": 6, "checklist": []}'::jsonb),
  ('Pasto - Limpeza (Ossos, Lascas, Galhos,Pedras,Arame)', 'Geral', '2 - Estratégica', 3, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Percorrer o pasto em faixas\n2. Recolher ossos, galhos, pedras, lascas e arame solto\n3. Juntar tudo na carreta\n4. Levar ao local de descarte\n5. Anotar os pastos limpos", "m3": "Trator com carreta", "m4": "Luvas", "m5": "Pasto limpo, sem risco para o gado e para as máquinas", "meta_qtd": 10, "meta_unid": "Hectares", "tempo_h": 6, "checklist": []}'::jsonb),
