  ('Pasto - Manutenção de Represas', 'Operacional', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Conferir o talude e o vertedouro\n2. Retirar o mato do talude\n3. Tapar buracos de tatu e erosões\n4. Desentupir o vertedouro\n5. Anotar o nível da água", "m3": "Enxada, roçadeira", "m4": "Terra para aterro", "m5": "Represa sem vazamento e com vertedouro livre", "meta_qtd": 1, "meta_unid": "Represa", "tempo_h": 4, "checklist": []}'::jsonb),
  ('Pasto - Plantio Lavoura / Silo / Capim', 'Máquinas', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Conferir o preparo do solo e a umidade\n2. Regular a plantadeira para a semente e a quantidade\n3. Plantar em nível\n4. Conferir a profundidade e a distribuição no começo\n5. Anotar a área, a semente e a quantidade usada", "m3": "Trator e plantadeira", "m4": "Sementes, adubo", "m5": "Área plantada com estande uniforme", "meta_qtd": 10, "meta_unid": "Hectares", "tempo_h": 8, "checklist": []}'::jsonb),
  ('Volumoso - Ensilagem', 'Máquinas', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Conferir o ponto de colheita da lavoura\n2. Regular a ensiladeira no tamanho de partícula certo\n3. Encher o silo em camadas finas e compactar bem\n4. Fechar e vedar o silo no mesmo dia\n5. Anotar as toneladas e a data", "m3": "Ensiladeira, carretas, trator de compactação", "m4": "Lona, peso para lona", "m5": "Silo bem compactado e vedado no mesmo dia", "meta_qtd": 1, "meta_unid": "Silo", "tempo_h": 10, "checklist": ["Ponto de colheita conferido", "Tamanho de partícula regulado", "Camadas compactadas", "Silo vedado no mesmo dia"]}'::jsonb),
  ('Silo - Cerca / cobrir monte / Manutenção', 'Operacional', '4 - Estruturação', 1, '{true,true,false,false,false,false,false}'::boolean[], '{"m2": "1. Conferir furos e rasgos na lona\n2. Remendar a lona\n3. Colocar peso em cima da lona (pneus ou terra)\n4. Conferir a cerca em volta do silo\n5. Manter a área limpa, sem mato e sem rato", "m3": "Alicate", "m4": "Fita para lona, pneus, arame", "m5": "Silo vedado e protegido", "meta_qtd": 1, "meta_unid": "Silo", "tempo_h": 2, "checklist": []}'::jsonb),
  ('Erosão - Contenção', 'Máquinas', '2 - Estratégica', 1, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Marcar a erosão e de onde vem a água\n2. Desviar a água com curva de nível ou bigode\n3. Aterrar e compactar o buraco\n4. Plantar capim ou cobrir o solo\n5. Voltar depois da próxima chuva e conferir", "m3": "Pá carregadeira, patrol", "m4": "Terra, sementes de capim", "m5": "Erosão contida e água desviada", "meta_qtd": 1, "meta_unid": "Erosão", "tempo_h": 6, "checklist": []}'::jsonb),
  ('Máquinas - Manutenção', 'Máquinas', '2 - Estratégica', 3, '{false,false,false,false,true,false,false}'::boolean[], '{"m2": "1. Anotar o defeito que o operador relatou\n2. Conferir a causa antes de trocar peça\n3. Fazer o conserto ou chamar a oficina\n4. Testar a máquina depois do conserto\n5. Anotar peças trocadas, custo e horímetro", "m3": "Ferramentas da oficina", "m4": "Peças, óleo, graxa", "m5": "Máquina consertada e testada", "meta_qtd": 1, "meta_unid": "Máquina", "tempo_h": 4, "checklist": []}'::jsonb),
  ('Implementos - Organização/ Manutenção', 'Máquinas', '2 - Estratégica', 2, '{true,true,true,true,true,false,false}'::boolean[], '{"m2": "1. Guardar cada implemento no lugar dele, na sombra\n2. Engraxar e conferir rolamentos\n3. Conferir lâminas, discos e pinos\n4. Trocar o que estiver gasto ou quebrado\n5. Anotar o que precisa de peça", "m3": "Engraxadeira, chaves", "m4": "Graxa, pinos, peças", "m5": "Implementos guardados e prontos para usar", "meta_qtd": 4, "meta_unid": "Implementos", "tempo_h": 4, "checklist": []}'::jsonb),
  ('Oficina - Limpeza', 'Máquinas', '2 - Estratégica', 3, '{false,false,false,false,false,true,false}'::boolean[], '{"m2": "1. Recolher estopas, latas e peças velhas\n2. Jogar serragem no óleo do chão e varrer\n3. Limpar bancada e ferramentas\n4. Separar o óleo usado no tambor certo\n5. Deixar o lixo separado para o descarte", "m3": "Vassoura, pá", "m4": "Serragem, sacos", "m5": "Oficina limpa e sem óleo no chão", "meta_qtd": 1, "meta_unid": "Oficina", "tempo_h": 2, "checklist": []}'::jsonb),
  ('Veículos - Limpeza', 'Gerencial', '2 - Estratégica', 2, '{false,false,false,false,false,true,false}'::boolean[], '{"m2": "1. Retirar o lixo de dentro\n2. Lavar por fora, inclusive a parte de baixo\n3. Limpar o painel e os bancos\n4. Conferir se não ficou ferramenta solta\n5. Guardar na garagem", "m3": "Mangueira ou lava-jato", "m4": "Detergente, panos", "m5": "Veículo limpo por dentro e por fora", "meta_qtd": 1, "meta_unid": "Veículo", "tempo_h": 1, "checklist": []}'::jsonb),
  ('Vagão - Limpeza', 'Máquinas', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Esvaziar a sobra de ração\n2. Lavar a caixa e as roscas\n3. Retirar ração grudada e mofada\n4. Conferir as facas e a balança do vagão\n5. Engraxar depois de lavar", "m3": "Lava-jato, raspador", "m4": "Graxa", "m5": "Vagão limpo, sem ração velha", "meta_qtd": 1, "meta_unid": "Vagão", "tempo_h": 2, "checklist": []}'::jsonb),
  ('Vagão - Manutenção', 'Máquinas', '2 - Estratégica', 2, '{false,false,false,true,false,false,false}'::boolean[], '{"m2": "1. Conferir correntes, roscas e facas\n2. Engraxar todos os pontos\n3. Conferir a balança do vagão com um peso conhecido\n4. Conferir o cardan e os pneus\n5. Anotar peças trocadas", "m3": "Engraxadeira, chaves", "m4": "Graxa, peças", "m5": "Vagão funcionando e balança aferida", "meta_qtd": 1, "meta_unid": "Vagão", "tempo_h": 3, "checklist": ["Correntes e roscas", "Facas", "Graxa", "Balança aferida", "Cardan e pneus"]}'::jsonb),
  ('Poço Artesiano - Manutenção', 'Operacional', '4 - Estruturação', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Conferir a bomba, o quadro elétrico e o horímetro\n2. Conferir a vazão e se tem barulho ou vibração\n3. Conferir a tampa do poço e a área em volta\n4. Limpar a área e tirar o mato\n5. Anotar o horímetro e o que encontrou", "m3": "Multímetro, chaves", "m4": "EPI", "m5": "Poço funcionando e protegido", "meta_qtd": 1, "meta_unid": "Poço", "tempo_h": 2, "checklist": []}'::jsonb),
  ('Rede Hidraulica - Manutenção - Instalação', 'Operacional', '2 - Estratégica', 3, '{false,true,false,true,false,false,false}'::boolean[], '{"m2": "1. Percorrer a rede procurando vazamentos\n2. Fechar o registro antes do conserto\n3. Trocar canos e conexões danificados\n4. Testar a pressão depois do conserto\n5. Anotar onde foi o conserto", "m3": "Serra, chaves, enxada", "m4": "Canos, conexões, cola, veda-rosca", "m5": "Rede sem vazamento", "meta_qtd": 1, "meta_unid": "Rodada", "tempo_h": 4, "checklist": []}'::jsonb),
  ('Reservatório - Monitoramento do Nível', 'Gerencial', '2 - Estratégica', 2, '{true,true,true,true,true,true,true}'::boolean[], '{"m2": "1. Ler o nível do reservatório no mesmo horário\n2. Anotar o nível\n3. Conferir se a bomba está ligando e desligando certo\n4. Avisar se o nível estiver baixando fora do normal", "m3": "Régua ou boia de nível", "m4": "Planilha ou app", "m5": "Nível anotado todos os dias", "meta_qtd": 1, "meta_unid": "Leitura", "tempo_h": 0.2, "checklist": []}'::jsonb),
  ('Alojamento - Limpeza - Manutenção', 'Geral', '1 - Rotina', 2, '{false,false,false,true,false,false,false}'::boolean[], '{"m2": "1. Varrer e lavar quartos, banheiros e cozinha\n2. Recolher o lixo\n3. Conferir lâmpadas, tomadas, chuveiro e torneiras\n4. Anotar consertos necessários\n5. Manter a área externa limpa", "m3": "Vassoura, rodo, balde", "m4": "Produtos de limpeza", "m5": "Alojamento limpo e sem conserto pendente", "meta_qtd": 1, "meta_unid": "Alojamento", "tempo_h": 3, "checklist": []}'::jsonb),
  ('Sede - Roçar a Grama', 'Operacional', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Retirar pedras e objetos do gramado\n2. Conferir a roçadeira e o combustível\n3. Roçar na altura combinada\n4. Varrer ou rastelar a grama cortada\n5. Limpar e guardar a roçadeira", "m3": "Roçadeira costal ou cortador", "m4": "Combustível, fio de nylon, EPI (óculos e protetor)", "m5": "Gramado da sede aparado", "meta_qtd": 1, "meta_unid": "Gramado", "tempo_h": 3, "checklist": []}'::jsonb),
  ('Sede - Limpeza Placa Solar', 'Administrativo', '2 - Estratégica', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Limpar as placas com pano e água, sem produto abrasivo\n2. Fazer de manhã cedo ou no fim da tarde\n3. Conferir cabos e conexões\n4. Anotar a geração do inversor antes e depois", "m3": "Escada, pano, rodo macio", "m4": "Água limpa, EPI (cinto se for no telhado)", "m5": "Placas limpas", "meta_qtd": 1, "meta_unid": "Limpeza", "tempo_h": 2, "checklist": ["Escada firme e cinto em uso", "Sem produto abrasivo", "Geração anotada"]}'::jsonb),
  ('Depósito de Defensivos - Limpeza e organização', 'Gerencial', '5 - Projeto', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Usar EPI completo\n2. Organizar os produtos por tipo, com o rótulo para frente\n3. Separar embalagens vazias para a tríplice lavagem e devolução\n4. Conferir vazamentos e limpar com material absorvente\n5. Manter o depósito trancado e com placa de aviso", "m3": "Prateleiras, pá", "m4": "Material absorvente, EPI completo", "m5": "Depósito organizado, sem vazamento e trancado", "meta_qtd": 1, "meta_unid": "Depósito", "tempo_h": 2, "checklist": ["EPI completo em uso", "Produtos organizados", "Embalagens vazias separadas", "Sem vazamento", "Depósito trancado"]}'::jsonb),
  ('Gestão - Reunião Mensal - 1 hora', 'Gerencial', '1 - Rotina', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Começar no horário, com o Painel do mês na tela\n2. Ver as metas e os indicadores do mês\n3. Ver o que deu certo e o que travou\n4. Combinar as prioridades do próximo mês\n5. Anotar os compromissos e quem cuida de cada um", "m3": "Computador ou TV com o Farm Plan", "m4": "Relatório Mensal, indicadores", "m5": "Reunião de 1 hora com prioridades e responsáveis anotados", "meta_qtd": 1, "meta_unid": "Reunião", "tempo_h": 1, "checklist": []}'::jsonb),
  ('Reunião Geral', 'Administrativo', '3 - Gestão', 2, '{true,false,false,false,false,false,false}'::boolean[], '{"m2": "1. Avisar a equipe com antecedência\n2. Começar no horário\n3. Passar os resultados e os recados\n4. Ouvir a equipe\n5. Anotar os combinados", "m3": "Local para todos sentados", "m4": "Pauta", "m5": "Equipe informada e combinados anotados", "meta_qtd": 1, "meta_unid": "Reunião", "tempo_h": 1, "checklist": []}'::jsonb)
) as m(nome, setor, tipo, urg, dias, cf)
on conflict (conta_id, chave) do update
  set como_fazer = excluded.como_fazer
  where coalesce(biblioteca.como_fazer->>'m2', '') = '';

select count(*) filter (where coalesce(como_fazer->>'m2', '') <> '') || ' de ' || count(*) || ' atividades da Biblioteca têm 5M' as resultado
from biblioteca;
